        # month -> {name: size_bytes}
        self._files_by_month: dict[str, dict[str, int]] = {}

    def upload(self, name: str, size_bytes: int, month: str) -> None:
        if size_bytes == 0:
            raise ValueError("Cannot upload a file of size 0.")

        files = self._files_by_month.setdefault(month, {})

        # Re-uploading an existing name in the same month: no double-count.
        if name in files:
            files[name] = size_bytes
            return

        if self.used_bytes(month) + size_bytes > self._limit_bytes:
            raise ValueError("Upload would exceed the monthly quota.")

        files[name] = size_bytes

    def delete(self, name: str, month: str) -> None:
        files = self._files_by_month.get(month)
        if files is not None:
            files.pop(name, None)

    def used_bytes(self, month: str) -> int:
        return sum(self._files_by_month.get(month, {}).values())
